export function formatTime(t){if(!isFinite(t)||t<0)return"0:00";const e=Math.floor(t/60),r=Math.floor(t%60);return`${e}:${r.toString().padStart(2,"0")}`}export function isCustomTheme(t,e=[]){return e.includes(t)}export function isValidMode(t,e=["light","dark","high-contrast"]){return e.includes(t)}export function calculateProgress(t,e){return!e||isNaN(t)||isNaN(e)?0:Math.max(0,Math.min(100,t/e*100))}export function escapeHtml(t){return t.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&#39;")}export function enableJs(){document.documentElement.setAttribute("data-luz-js","")}
